pageCss:
.rg-box{border:1px solid var(--slate-73);background:var(--row-alt);box-shadow:inset 1px 1px 0 var(--paper);padding:8px 10px;margin:10px 0}
.rg-pad{font-size:var(--text-xs)}
.rg-controls{display:flex;flex-wrap:wrap;gap:6px 12px;align-items:center;font-size:var(--text-xs);margin:0 0 8px}
.rg-controls .xp-button{font-size:var(--text-micro)}
.rg-strip{display:grid;gap:1px;background:var(--slate-81);border:1px solid var(--slate-73);cursor:crosshair;margin:4px 0 2px}
.rg-strip span{display:block;height:22px;background:var(--paper)}
.rg-strip .part{background:var(--blue-80)}
.rg-strip .have{background:var(--blue-55)}
.rg-strip .fresh{background:var(--go)}
.rg-strip .read{box-shadow:inset 0 0 0 2px var(--warn)}
.rg-cap{font-size:var(--text-2xs);color:var(--ink-dim);margin:2px 0 8px}
.rg-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:0 0 8px}
.rg-stats>div,.rg-race .leg{border:1px solid var(--slate-81);background:var(--paper);padding:6px 8px;font-size:var(--text-micro)}
.rg-stats .n,.rg-race .n{font-family:var(--font-mono);font-size:var(--text-lede);font-weight:700;display:block}
.rg-stats .lbl,.rg-race .lbl{color:var(--slate-40)}
.rg-log{margin:0;padding-left:18px;font-size:var(--text-micro);color:var(--ink-soft);min-height:4em}
.rg-log li:first-child{color:var(--ink)}
.rg-box .n{font-family:var(--font-mono);font-weight:700}
.rg-legend{font-size:var(--text-2xs);color:var(--ink-dim);margin:0 0 6px}
.rg-legend span{display:inline-block;width:10px;height:10px;margin:0 3px 0 10px;vertical-align:-1px}
.rg-legend span:first-child{margin-left:0}
.rg-lanes{border:1px solid var(--slate-81);background:var(--paper);padding:4px 0}
.lane{display:grid;grid-template-columns:5.5em 1fr;align-items:center;font-size:var(--text-2xs);padding:1px 8px}
.lane.origin{border-bottom:1px solid var(--rule);padding-bottom:4px;margin-bottom:3px}
.lane .who{color:var(--slate-40)}
.lane .track{position:relative;height:9px}
.lane .track span{position:absolute;top:0;height:9px;transform-origin:left;animation:rg-grow var(--xp-transition-move) both}
.rg-legend .own,.lane .own{background:var(--go)}
.rg-legend .ride,.lane .ride{background:var(--blue-55)}
.rg-legend .hit,.lane .hit{background:var(--slate-81)}
.rg-legend .fetch,.lane .fetch{background:var(--amber-56);opacity:.55}
@keyframes rg-grow{from{transform:scaleX(0)}to{transform:scaleX(1)}}
@media (prefers-reduced-motion:reduce){.lane .track span{animation:none}}
.rg-sum{font-size:var(--text-xs);margin:8px 0 0}
.rg-live-grid{display:grid;grid-template-columns:200px 1fr;gap:10px;align-items:start}
.rg-thumb{width:200px;height:auto;border:1px solid var(--slate-73);background:var(--paper)}
.rg-boxes .row{display:grid;grid-template-columns:6.5em minmax(0,1.6fr) 6.5em minmax(0,1fr) 4em;gap:8px;align-items:center;padding:2px 6px;font-size:var(--text-micro);border-bottom:1px solid var(--surface-desktop);background:var(--paper)}
.rg-boxes .row.head{font-weight:700;background:var(--surface-desktop)}
.rg-boxes .row span:nth-child(1),.rg-boxes .row span:nth-child(3),.rg-boxes .row span:nth-child(5){font-family:var(--font-mono);font-size:var(--text-2xs);text-align:right}
.rg-boxes .row.head span{font-family:inherit;font-size:inherit}
.rg-boxes .share{display:block;height:9px;border:1px solid var(--slate-81);background:var(--paper)}
.rg-boxes .share i{display:block;height:100%;background:var(--blue-55)}
.rg-race{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:8px 0 0;font-size:var(--text-xs)}
.rg-race:empty{display:none}
@media (max-width:640px){.rg-stats{grid-template-columns:1fr 1fr}.rg-live-grid,.rg-race{grid-template-columns:1fr}.rg-boxes .row{grid-template-columns:5.5em minmax(0,1fr) 5.5em 3.5em}.rg-boxes .row span:nth-child(4){display:none}}

