(function(){
  var $ = function(id){ return document.getElementById(id); };
  var KiB = 1024, MiB = 1048576, GiB = 1073741824;
  var commas = function(n){ return n.toLocaleString("en-US"); };
  // Binary units throughout, because the chunk sizes are powers of two and the
  // post quotes R2's old range as 64 MiB.
  var human = function(n){
    var u = n >= GiB ? [GiB, "GiB"] : n >= MiB ? [MiB, "MiB"] : n >= KiB ? [KiB, "KiB"] : [1, "B"];
    var v = n / u[0];
    return (u[0] === 1 || v >= 100 || v === Math.round(v) ? String(Math.round(v)) : v.toFixed(v >= 10 ? 1 : 2)) + " " + u[1];
  };
  var esc = function(s){ return String(s).replace(/[&<>"]/g, function(c){ return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; }); };
  var median = function(xs){ var s = xs.slice().sort(function(a, b){ return a - b; }); var m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };

  // ── 1. chunk simulator ──────────────────────────────────────────────
  // One model for both eras: a read fetches every touched chunk it doesn't
  // hold, whole, and one origin request covers each run of adjacent misses.
  // The old R2 behavior is this model at 64 MiB.
  (function(){
    var box = $("rg-sim");
    if (!box) return;
    var FILES = { photo: 9270366, video: 524288000, disk: 4 * GiB };
    var CELLS = 96;
    var strip = $("rg-strip"), stats = $("rg-stats"), log = $("rg-log"), file = $("rg-file"), chunkSel = $("rg-chunk");
    var st;
    function reset(){
      var size = FILES[file.value], chunk = +chunkSel.value, n = Math.ceil(size / chunk);
      st = { size: size, chunk: chunk, n: n, have: new Uint8Array(n), fresh: new Uint8Array(n), asked: 0, sent: 0, reqs: 0, last: null };
      log.innerHTML = "";
      draw();
    }
    function read(start, len, label){
      start = Math.max(0, Math.min(start, st.size - 1));
      var end = Math.min(st.size - 1, start + len - 1);
      var a = Math.floor(start / st.chunk), b = Math.floor(end / st.chunk);
      var fetched = 0, runs = 0, hit = 0, inRun = false;
      st.fresh.fill(0);
      for (var c = a; c <= b; c++) {
        if (st.have[c]) { hit++; inRun = false; continue; }
        if (!inRun) { runs++; inRun = true; }
        fetched += Math.min(st.chunk, st.size - c * st.chunk);
        st.have[c] = 1; st.fresh[c] = 1;
      }
      var asked = end - start + 1, touched = b - a + 1;
      st.asked += asked; st.sent += fetched; st.reqs += runs; st.last = [start, end];
      var li = document.createElement("li");
      li.textContent = label + ": " + human(asked) + " at byte " + commas(start) + " touches " + touched + (touched === 1 ? " chunk" : " chunks") +
        (hit ? " (" + hit + " cached)" : "") + ". " + (fetched ? "Origin sends " + human(fetched) + " in " + runs + (runs === 1 ? " request." : " requests.") : "Served from cache, origin untouched.");
      log.insertBefore(li, log.firstChild);
      while (log.children.length > 6) log.removeChild(log.lastChild);
      draw();
    }
    function draw(){
      var cells = Math.min(CELLS, st.n), html = "";
      for (var i = 0; i < cells; i++) {
        var c0 = Math.floor(i * st.n / cells), c1 = Math.floor((i + 1) * st.n / cells), have = 0, fresh = 0;
        for (var c = c0; c < c1; c++) { have += st.have[c]; fresh |= st.fresh[c]; }
        var cls = fresh ? "fresh" : have === c1 - c0 ? "have" : have ? "part" : "";
        if (st.last) {
          var b0 = c0 * st.chunk, b1 = Math.min(st.size, c1 * st.chunk) - 1;
          if (st.last[0] <= b1 && st.last[1] >= b0) cls += " read";
        }
        html += '<span class="' + cls + '"></span>';
      }
      strip.innerHTML = html;
      strip.style.gridTemplateColumns = "repeat(" + cells + ",1fr)";
      var held = 0;
      for (var k = 0; k < st.n; k++) held += st.have[k];
      var amp = st.asked ? st.sent / st.asked : 0;
      stats.innerHTML =
        '<div><span class="n">' + human(st.asked) + '</span><span class="lbl">clients asked for</span></div>' +
        '<div><span class="n">' + human(st.sent) + '</span><span class="lbl">origin sent' + (st.asked ? " (" + (amp >= 10 ? commas(Math.round(amp)) : amp.toFixed(1)) + "x)" : "") + '</span></div>' +
        '<div><span class="n">' + commas(st.reqs) + '</span><span class="lbl">origin requests</span></div>' +
        '<div><span class="n">' + commas(held) + " / " + commas(st.n) + '</span><span class="lbl">chunks cached</span></div>';
      $("rg-geom").textContent = commas(st.size) + " bytes in " + commas(st.n) + (st.n === 1 ? " chunk" : " chunks") + " of " + human(st.chunk) +
        (st.n > CELLS ? ", about " + commas(Math.round(st.n / CELLS)) + " chunks per square" : ", one per square") + ".";
    }
    var READS = {
      head: function(){ read(0, KiB, "Header"); },
      tail: function(){ read(st.size - 64 * KiB, 64 * KiB, "Tail"); },
      edge: function(){ read(st.n > 1 ? st.chunk - 512 : Math.floor(st.size / 2), KiB, "Edge"); },
      scrub: function(){ for (var k = 0; k < 8; k++) read(Math.floor(st.size * (k + 0.5) / 8), MiB, "Seek " + (k + 1)); }
    };
    box.addEventListener("click", function(e){
      var t = e.target.closest("[data-read]");
      if (t) { READS[t.getAttribute("data-read")](); return; }
      if (e.target.closest("#rg-reset")) reset();
    });
    strip.addEventListener("click", function(e){
      var r = strip.getBoundingClientRect();
      read(Math.floor((e.clientX - r.left) / r.width * st.size), MiB, "Click");
    });
    file.addEventListener("change", reset);
    chunkSel.addEventListener("change", reset);
    box.hidden = false;
    reset();
  })();

  // ── 2. in-flight sharing ────────────────────────────────────────────
  // Viewers arrive 30 ms apart (plus seeded jitter) and each wants 2 MiB near
  // the same spot of a cold 500 MB file. A fetch takes FETCH_MS. Shared, a
  // viewer waits on a chunk already in flight; unshared, it fetches its own copy.
  (function(){
    var box = $("rg-share");
    if (!box) return;
    var FETCH_MS = 300, CHUNK = MiB, SPAN = 1000;
    var countEl = $("rg-viewers"), shareEl = $("rg-shared"), out = $("rg-lanes"), sum = $("rg-share-stats");
    function rng(seed){ return function(){ seed |= 0; seed = seed + 0x6D2B79F5 | 0; var t = Math.imul(seed ^ seed >>> 15, 1 | seed); t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t; return ((t ^ t >>> 14) >>> 0) / 4294967296; }; }
    function simulate(n, shared){
      var rand = rng(7), done = {}, flying = {}, viewers = [], fetches = [];
      for (var i = 0; i < n; i++) {
        var at = i * 30 + Math.floor(rand() * 20), first = 100 + Math.floor(rand() * 3), wait = at, own = 0, rode = 0;
        for (var c = first; c < first + 2; c++) {
          if (done[c] !== undefined && done[c] <= at) continue;
          if (shared && flying[c] !== undefined && flying[c] > at) { rode++; wait = Math.max(wait, flying[c]); continue; }
          own++;
          var end = at + FETCH_MS;
          fetches.push([at, end]);
          if (flying[c] === undefined || !shared) flying[c] = end;
          if (done[c] === undefined || end < done[c]) done[c] = end;
          wait = Math.max(wait, end);
        }
        viewers.push({ at: at, end: wait, kind: own ? "own" : rode ? "ride" : "hit" });
      }
      return { viewers: viewers, fetches: fetches };
    }
    function bar(cls, a, b, label){
      return '<span class="' + cls + '" style="left:' + (a / SPAN * 100).toFixed(2) + "%;width:" + Math.max(0.6, (b - a) / SPAN * 100).toFixed(2) + '%"' + (label ? ' title="' + esc(label) + '"' : "") + "></span>";
    }
    function run(){
      var n = +countEl.value, shared = shareEl.checked, r = simulate(n, shared), html = "";
      $("rg-viewers-n").textContent = n;
      html += '<div class="lane origin"><span class="who">origin</span><span class="track">';
      r.fetches.forEach(function(f){ html += bar("fetch", f[0], f[1]); });
      html += "</span></div>";
      r.viewers.forEach(function(v, i){
        html += '<div class="lane"><span class="who">viewer ' + (i + 1) + '</span><span class="track">' +
          bar(v.kind, v.at, Math.max(v.end, v.at + 8), v.kind === "own" ? "started an origin fetch" : v.kind === "ride" ? "waited on a fetch already running" : "served from cache") + "</span></div>";
      });
      out.innerHTML = html;
      var waits = r.viewers.map(function(v){ return v.end - v.at; });
      sum.innerHTML = '<span class="n">' + r.fetches.length + "</span> origin " + (r.fetches.length === 1 ? "fetch" : "fetches") + ', <span class="n">' + human(r.fetches.length * CHUNK) +
        '</span> from the origin, median wait <span class="n">' + Math.round(median(waits)) + " ms</span>.";
    }
    countEl.addEventListener("input", run);
    shareEl.addEventListener("change", run);
    box.hidden = false;
    run();
  })();

  // ── 3. live: walk a photo original with range reads ─────────────────
  (function(){
    var box = $("rg-live");
    if (!box || !window.fetch || !window.AbortController) return;
    var pick = $("rg-photo"), walkBtn = $("rg-walk"), raceBtn = $("rg-race"), out = $("rg-boxes"), sumEl = $("rg-walk-sum"), raceEl = $("rg-race-out"), thumb = $("rg-thumb");
    var HOP = 32;
    var KINDS = { "JXL ": "signature", ftyp: "file type", jxll: "level", jxlc: "codestream", jxlp: "codestream part", jxli: "frame index", jbrd: "JPEG reconstruction data", brob: "Brotli-compressed", Exif: "EXIF", "xml ": "XMP", jumb: "JUMBF" };
    var four = function(u, o){ return String.fromCharCode(u[o], u[o + 1], u[o + 2], u[o + 3]); };
    var photos = {};

    // A range read that refuses to turn into a 30 MB download: a server that
    // ignores Range answers 200, and this aborts before reading that body.
    async function ranged(url, a, b){
      var ctrl = new AbortController(), t0 = performance.now();
      var r = await fetch(url, { headers: { Range: "bytes=" + a + "-" + b }, cache: "no-store", signal: ctrl.signal });
      if (r.status !== 206) { ctrl.abort(); throw new Error(url + " answered " + r.status + " to a range request"); }
      var buf = new Uint8Array(await r.arrayBuffer());
      var total = +((r.headers.get("content-range") || "").split("/")[1] || 0);
      return { bytes: buf, total: total, ms: performance.now() - t0, edge: r.headers.get("cf-cache-status"), ray: r.headers.get("cf-ray") };
    }

    // JPEG XL SizeHeader (ISO/IEC 18181-1), read LSB first from just after the
    // FF 0A codestream signature.
    function sizeHeader(u, o){
      var bit = 0;
      var bits = function(n){ var v = 0; for (var k = 0; k < n; k++) { v += ((u[o + (bit >> 3)] >> (bit & 7)) & 1) * Math.pow(2, k); bit++; } return v; };
      var u32 = function(){ return bits([9, 13, 18, 30][bits(2)]) + 1; };
      var small = bits(1), h = small ? (bits(5) + 1) * 8 : u32(), ratio = bits(3);
      var R = [null, [1, 1], [12, 10], [4, 3], [3, 2], [16, 9], [5, 4], [2, 1]];
      var w = ratio ? Math.floor(h * R[ratio][0] / R[ratio][1]) : small ? (bits(5) + 1) * 8 : u32();
      return [w, h];
    }

    async function walk(){
      var url = pick.value, rows = [], dims = null, off = 0, total = Infinity, read = 0, ms = [], cached = 0;
      walkBtn.disabled = raceBtn.disabled = true;
      out.innerHTML = ""; sumEl.textContent = "Walking " + url + " ...";
      try {
        while (off < total && rows.length < 64) {
          var got = await ranged(url, off, off + HOP - 1), u = got.bytes;
          total = got.total; read += u.length; ms.push(got.ms);
          if (got.edge) cached++;
          if (off === 0 && u[0] === 0xff && u[1] === 0x0a) { dims = sizeHeader(u, 2); rows.push({ off: 0, size: total, type: "bare", ms: got.ms }); break; }
          var size = ((u[0] << 24) >>> 0) + (u[1] << 16) + (u[2] << 8) + u[3], type = four(u, 4), hdr = 8;
          if (size === 1) { size = (((u[8] << 24) >>> 0) + (u[9] << 16) + (u[10] << 8) + u[11]) * 4294967296 + ((u[12] << 24) >>> 0) + (u[13] << 16) + (u[14] << 8) + u[15]; hdr = 16; }
          if (size === 0) size = total - off;
          var inner = type === "brob" ? four(u, hdr) : "";
          if (!dims && (type === "jxlc" || type === "jxlp")) {
            var cs = hdr + (type === "jxlp" ? 4 : 0);
            if (u[cs] === 0xff && u[cs + 1] === 0x0a) dims = sizeHeader(u, cs + 2);
          }
          rows.push({ off: off, size: size, type: type, inner: inner, ms: got.ms, ray: got.ray });
          paint(rows, total);
          off += size;
        }
        paint(rows, total);
        var biggest = rows.reduce(function(m, r){ return r.size > m.size ? r : m; }, rows[0]);
        var colo = (rows[0].ray || "").split("-")[1];
        sumEl.innerHTML = '<span class="n">' + rows.length + "</span> range requests read <span class=\"n\">" + commas(read) + "</span> of " + commas(total) +
          " bytes (" + (read / total * 100).toPrecision(2) + "%)" + (dims ? ". The codestream header says the image is <span class=\"n\">" + dims[0] + " x " + dims[1] + "</span>" : "") +
          ", and its largest box, the " + esc(KINDS[biggest.type] || biggest.type) + ", is " + (biggest.size / total * 100).toFixed(1) + "% of the file. " +
          (cached ? cached + " of " + rows.length + " answers carried cf-cache-status" : "None of the " + rows.length + " answers carried cf-cache-status, so every hop ran the Worker and read R2") +
          (colo ? ", through the " + esc(colo) + " colo" : "") + ". Median hop: <span class=\"n\">" + Math.round(median(ms)) + " ms</span>.";
      } catch (e) {
        sumEl.textContent = "The walk stopped: " + e.message + ".";
      }
      walkBtn.disabled = raceBtn.disabled = false;
    }
    function paint(rows, total){
      out.innerHTML = '<div class="row head"><span>offset</span><span>box</span><span>size</span><span>share of file</span><span>hop</span></div>' +
        rows.map(function(r){
          var name = r.type === "bare" ? "bare codestream" : (KINDS[r.type] || "unknown") + (r.inner ? " " + (KINDS[r.inner] || r.inner) : "");
          return '<div class="row"><span>' + commas(r.off) + "</span><span><code>" + esc(r.type.trim() || r.type) + "</code> " + esc(name) + "</span><span>" + commas(r.size) +
            '</span><span class="share"><i style="width:' + Math.max(0.5, r.size / total * 100).toFixed(2) + '%"></i></span><span>' + Math.round(r.ms) + " ms</span></div>";
        }).join("");
    }

    // Time to response headers, nothing more. The full GET is aborted as soon as
    // they land, so the race doesn't pull a whole original per round (some of the body is in
    // flight by then anyway). Order alternates per round so neither path always
    // goes first on the shared connection.
    async function headersIn(url, range){
      var ctrl = new AbortController(), t0 = performance.now(), opts = { cache: "no-store", signal: ctrl.signal };
      if (range) opts.headers = { Range: range };
      var r = await fetch(url, opts), ms = performance.now() - t0, edge = r.headers.get("cf-cache-status"), age = r.headers.get("age");
      if (range && r.status === 206) await r.arrayBuffer(); else ctrl.abort();
      return { ms: ms, status: r.status, edge: edge, age: age === null ? null : +age };
    }
    async function race(){
      var url = pick.value, ROUNDS = 5, full = [], part = [];
      walkBtn.disabled = raceBtn.disabled = true;
      raceEl.textContent = "Racing ...";
      try {
        for (var i = 0; i < ROUNDS; i++) {
          var pair = i % 2 ? [await headersIn(url, "bytes=0-1023"), await headersIn(url)].reverse() : [await headersIn(url), await headersIn(url, "bytes=0-1023")];
          full.push(pair[0]); part.push(pair[1]);
        }
        var hits = full.filter(function(r){ return r.edge === "HIT"; }).length, partTagged = part.filter(function(r){ return r.edge; }).length;
        var ages = full.filter(function(r){ return r.age !== null; }).map(function(r){ return r.age; });
        raceEl.innerHTML =
          '<div class="leg"><span class="n">' + Math.round(median(full.map(function(r){ return r.ms; }))) + ' ms</span><span class="lbl">full GET to headers, median of ' + ROUNDS + ". " +
          hits + " of " + ROUNDS + " answered cf-cache-status: HIT" + (ages.length ? ", the copy " + commas(Math.max.apply(null, ages)) + " s old" : "") + "</span></div>" +
          '<div class="leg"><span class="n">' + Math.round(median(part.map(function(r){ return r.ms; }))) + ' ms</span><span class="lbl">1 KiB range to headers, median of ' + ROUNDS + ". " +
          (partTagged ? partTagged + " carried cf-cache-status" : "none carried cf-cache-status, so every one ran the Worker and read R2") + "</span></div>";
      } catch (e) {
        raceEl.textContent = "The race stopped: " + e.message + ".";
      }
      walkBtn.disabled = raceBtn.disabled = false;
    }
    function showThumb(){
      var p = photos[pick.value];
      if (p && p.thumb && p.thumb.small) { thumb.src = p.thumb.small; thumb.alt = p.alt || ""; thumb.hidden = false; } else thumb.hidden = true;
    }

    fetch("/photos/query.json?limit=40").then(function(r){ if (!r.ok) throw new Error("/photos/query.json answered " + r.status); return r.json(); }).then(function(j){
      var list = (j.photos || []).filter(function(p){ return p.full; });
      if (!list.length) throw new Error("the photo list came back empty");
      pick.innerHTML = list.map(function(p){ photos[p.full] = p; return '<option value="' + esc(p.full) + '">' + esc(p.full.split("/").pop()) + "</option>"; }).join("");
      showThumb();
      pick.addEventListener("change", function(){ out.innerHTML = ""; sumEl.textContent = ""; raceEl.textContent = ""; showThumb(); });
      walkBtn.addEventListener("click", walk);
      raceBtn.addEventListener("click", race);
      box.hidden = false;
      $("rg-live-off").hidden = true;
    }).catch(function(e){
      $("rg-live-off").textContent = "The live probe couldn't load its photo list: " + e.message + ".";
    });
  })();
})();
